import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"CoreLib Actions","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/attribute/corelib-actions.md","filePath":"en/modules/attribute/corelib-actions.md","lastUpdated":0}`),a={name:`en/modules/attribute/corelib-actions.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="corelib-actions" tabindex="-1">CoreLib Actions <a class="header-anchor" href="#corelib-actions" aria-label="Permalink to “CoreLib Actions”">​</a></h1><p>When EmakiAttribute is enabled, it adds attribute, resource, tag, and sync stages to the CoreLib action registry. Use them anywhere CoreLib pipelines are accepted: Forge/Strengthen/Cooking/Skills/Item action lists, CoreLib pipeline templates, or pipelines triggered by other plugins through the CoreLib pipeline engine.</p><div class="note custom-block"><p class="custom-block-title custom-block-title-default">NOTE</p><p>This page documents only the stages registered by EmakiAttribute. CoreLib&#39;s own message, command, economy, and item stages are documented in <a href="./../corelib/actions.html">CoreLib Actions</a>. Current stage IDs use only the canonical names below; historical aliases are no longer registered. The old <code>attributedamage</code> is now written <code>attribute_damage</code>; the other stage IDs are unchanged.</p></div><p>Which entity is affected comes from the source: use <code>self</code> for the caster, or <code>player_by_name</code> for a named player.</p><h2 id="stage-id-reference" tabindex="-1">Stage ID reference <a class="header-anchor" href="#stage-id-reference" aria-label="Permalink to “Stage ID reference”">​</a></h2><table tabindex="0"><thead><tr><th>Stage ID</th><th>Purpose</th><th>Target requirement</th></tr></thead><tbody><tr><td><code>attribute_damage</code></td><td>Applies attribute-typed custom damage to the target.</td><td><code>REQUIRED_ENTITY</code></td></tr><tr><td><code>attribute_add</code></td><td>Adds a timed attribute modifier to the target.</td><td><code>REQUIRED_ENTITY</code></td></tr><tr><td><code>attribute_set</code></td><td>Sets a timed attribute modifier on the target.</td><td><code>REQUIRED_ENTITY</code></td></tr><tr><td><code>attribute_remove</code></td><td>Clears every timed modifier inside the target&#39;s <code>effect_id</code> group.</td><td><code>REQUIRED_ENTITY</code></td></tr><tr><td><code>attribute_resource_add</code></td><td>Adds to one of the target&#39;s resources.</td><td><code>REQUIRED_ENTITY</code></td></tr><tr><td><code>attribute_resource_set</code></td><td>Sets one of the target&#39;s resources.</td><td><code>REQUIRED_ENTITY</code></td></tr><tr><td><code>attribute_resource_remove</code></td><td>Removes from one of the target&#39;s resources.</td><td><code>REQUIRED_ENTITY</code></td></tr><tr><td><code>attribute_resource_consume</code></td><td>Consumes one of the target&#39;s resources.</td><td><code>REQUIRED_ENTITY</code></td></tr><tr><td><code>attribute_tag_add</code></td><td>Adds timed attribute modifiers in bulk by tag.</td><td><code>REQUIRED_ENTITY</code></td></tr><tr><td><code>attribute_tag_remove</code></td><td>Removes timed attribute modifiers by tag.</td><td><code>REQUIRED_ENTITY</code></td></tr><tr><td><code>attribute_tag_clear</code></td><td>Clears timed attribute modifiers by tag.</td><td><code>REQUIRED_ENTITY</code></td></tr><tr><td><code>attribute_sync</code></td><td>Recomputes attribute and resource state for the target or everyone online.</td><td><code>OPTIONAL</code></td></tr><tr><td><code>attribute_refresh</code></td><td>Drops attribute caches, then recomputes for the target or everyone online.</td><td><code>OPTIONAL</code></td></tr></tbody></table><p>Apart from the two sync stages, <code>attribute_damage</code> and the resource stages accept only player targets; the timed-attribute and tag stages accept any living entity (including non-player mobs) and skip non-living targets. <code>attribute_damage</code> declares <code>REQUIRED_ENTITY</code>, but the implementation only handles <code>Player</code>: a non-player living target is skipped with <code>not_player</code> and takes no damage.</p><div class="warning custom-block"><p class="custom-block-title">Upgrade notes: timed attribute behaviour changes</p><p>Two changes are visible to existing configuration:</p><ol><li><strong>The tag entry point no longer produces composite effect IDs.</strong> <code>attribute_tag_add effect_prefix=poison</code> used to write separate unrelated top-level records such as <code>poison:physical_attack</code> and <code>poison:movement_speed</code>; they now all join a single <code>poison</code> <strong>effect group</strong>. Configuration that deleted one composite ID such as <code>poison:physical_attack</code> no longer matches and must use <code>attribute_remove effect_id=poison</code> instead. Conversely, <code>attribute_remove effect_id=poison</code> — which previously removed nothing — now works.</li><li><strong>Multi-group SET on the same attribute now has a defined winner.</strong> It used to depend on internal hash-map iteration order, so the same configuration could produce different results and could change as the map grew. The last write now wins (highest internal monotonic revision), and repeated runs are stable. <code>/ea trace</code> marks the losing entry as overridden by a higher revision.</li></ol><p>Single-attribute configuration is unaffected and behaves exactly as before.</p></div><h2 id="attribute-damage" tabindex="-1">attribute_damage <a class="header-anchor" href="#attribute-damage" aria-label="Permalink to “attribute_damage”">​</a></h2><p>Applies one Attribute damage instance to the target. Unlike CoreLib&#39;s built-in <code>damage</code>, this stage routes through EmakiAttribute, so the module&#39;s damage types, resistances, and combat snapshot all apply.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>amount</code></td><td>DOUBLE</td><td>Yes</td><td>—</td><td>Base damage.</td></tr><tr><td><code>type</code></td><td>STRING</td><td>No</td><td><code>&quot;&quot;</code></td><td>Damage type ID. Empty uses EmakiAttribute&#39;s default damage type.</td></tr><tr><td><code>cause</code></td><td>STRING</td><td>No</td><td><code>CUSTOM</code></td><td>Bukkit <code>EntityDamageEvent.DamageCause</code>, such as <code>CUSTOM</code>, <code>MAGIC</code>, or <code>ENTITY_ATTACK</code>.</td></tr></tbody></table><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | attribute_damage amount=25 type=physical cause=CUSTOM&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;looking_at range=15 | attribute_damage amount=40 type=spell cause=MAGIC&#39;</span></span></code></pre></div><p>An unrecognised <code>cause</code> fails with <code>INVALID_CONFIG</code> rather than silently damaging with the wrong cause; a blank value means <code>CUSTOM</code>. Damage refused by the module&#39;s rules fails with <code>REJECTED</code>. On success the stage reports <code>damage_type</code>.</p><h2 id="timed-attribute-modifiers" tabindex="-1">Timed attribute modifiers <a class="header-anchor" href="#timed-attribute-modifiers" aria-label="Permalink to “Timed attribute modifiers”">​</a></h2><p><code>effect_id</code> identifies an <strong>effect group</strong>, not a single effect. Several attributes can share one <code>effect_id</code>: they coexist instead of overwriting each other, and <code>attribute_remove</code> clears the whole group at once. <code>attribute_add</code> and <code>attribute_set</code> decide whether <strong>that attribute&#39;s</strong> entry inside the group adds or overwrites, which is why they are separate stages rather than one stage with a mode argument.</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | attribute_add effect_id=buff_strength attribute=physical_attack value=10 duration_ticks=200t&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | attribute_add effect_id=buff_strength attribute=physical_crit_rate value=5 duration_ticks=200t&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | attribute_remove effect_id=buff_strength&#39;</span></span></code></pre></div><p>Both <code>attribute_add</code> calls above land in one group, and <code>attribute_remove</code> clears both attributes.</p><h3 id="attribute-add-attribute-set" tabindex="-1">attribute_add / attribute_set <a class="header-anchor" href="#attribute-add-attribute-set" aria-label="Permalink to “attribute_add / attribute_set”">​</a></h3><p>Both stages take the same arguments.</p><table tabindex="0"><thead><tr><th>Argument</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>effect_id</code></td><td>STRING</td><td>Yes</td><td>—</td><td>Effect group id; reusing one id groups several attributes together.</td></tr><tr><td><code>attribute</code></td><td>STRING</td><td>Yes</td><td>—</td><td>Attribute ID; an unregistered id fails with <code>INVALID_CONFIG</code>.</td></tr><tr><td><code>value</code></td><td>DOUBLE</td><td>Yes</td><td>—</td><td>Modifier value; <code>NaN</code> and <code>±Inf</code> fail with <code>INVALID_CONFIG</code>.</td></tr><tr><td><code>duration_ticks</code></td><td>DURATION</td><td>Yes</td><td>—</td><td>Duration; accepts <code>20t</code>, <code>1s</code>, <code>1000ms</code>; a bare number is ticks.</td></tr><tr><td><code>stack_mode</code></td><td>STRING</td><td>No</td><td>the attribute&#39;s <code>temporary_stack_mode</code></td><td>How to combine with an existing entry for the same attribute in that group: <code>REPLACE</code> overwrites, <code>STACK</code> adds value and remaining duration. An undeclared value fails with <code>INVALID_CONFIG</code>.</td></tr></tbody></table><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | attribute_add effect_id=forge_bonus attribute=physical_attack value=12 duration_ticks=10s&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | attribute_set effect_id=arena_buff attribute=physical_attack value=30 duration_ticks=200t&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | attribute_add effect_id=forge_bonus attribute=physical_attack value=3 duration_ticks=10s stack_mode=STACK&#39;</span></span></code></pre></div><h3 id="attribute-remove" tabindex="-1">attribute_remove <a class="header-anchor" href="#attribute-remove" aria-label="Permalink to “attribute_remove”">​</a></h3><table tabindex="0"><thead><tr><th>Argument</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>effect_id</code></td><td>STRING</td><td>Yes</td><td>—</td><td>Effect group id to clear; every attribute in that group is removed.</td></tr></tbody></table><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | attribute_remove effect_id=arena_buff&#39;</span></span></code></pre></div><p>All three stages normalise <code>effect_id</code> and <code>attribute</code> as IDs. A blank <code>effect_id</code> fails with <code>INVALID_CONFIG</code>; a non-living target is skipped with <code>not_living_entity</code> (non-player mobs are supported). When the target carries no such group the stage is <code>skipped</code> rather than successful. On success they report <code>effect_id</code>, <code>attribute</code>, <code>value</code>, <code>duration_ticks</code>, <code>status</code>, <code>affected_count</code>, <code>existed</code>, and <code>remaining_ticks</code>, where <code>status</code> is one of <code>APPLIED</code> / <code>REPLACED</code> / <code>STACKED</code> / <code>REMOVED</code>.</p><h2 id="resources" tabindex="-1">Resources <a class="header-anchor" href="#resources" aria-label="Permalink to “Resources”">​</a></h2><p>The four resource stages modify a player&#39;s current resource value through EmakiAttribute&#39;s resource sync boundary. They share one parameter set.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>resource</code></td><td>STRING</td><td>Yes</td><td>—</td><td>Resource ID, such as <code>health</code> or <code>mana</code>.</td></tr><tr><td><code>amount</code></td><td>DOUBLE</td><td>Yes</td><td>—</td><td>Operation amount.</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Stage ID</th><th>Arithmetic</th></tr></thead><tbody><tr><td><code>attribute_resource_add</code></td><td>current + <code>amount</code></td></tr><tr><td><code>attribute_resource_set</code></td><td>set to <code>amount</code></td></tr><tr><td><code>attribute_resource_remove</code></td><td>current - <code>amount</code>, floored at 0</td></tr><tr><td><code>attribute_resource_consume</code></td><td>identical to <code>attribute_resource_remove</code></td></tr></tbody></table><p><code>attribute_resource_consume</code> and <code>attribute_resource_remove</code> compute the same value. Both IDs are kept because existing configuration refers to them by name; they share one implementation.</p><p>The final value is still clamped by the resource definition&#39;s sync rules, so <code>add</code> cannot exceed the maximum.</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | attribute_resource_add resource=mana amount=10&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | attribute_resource_set resource=health amount=20&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | attribute_resource_remove resource=health amount=5&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | attribute_resource_consume resource=mana amount=20&#39;</span></span></code></pre></div><p><code>resource</code> is normalised as an ID; an unloaded resource fails with <code>INVALID_CONFIG</code>. On success the stage reports <code>resource</code>, <code>operation</code>, <code>amount</code>, <code>old_value</code>, <code>new_value</code>, and <code>current_max</code>.</p><h2 id="tag-addressed-timed-modifiers" tabindex="-1">Tag-addressed timed modifiers <a class="header-anchor" href="#tag-addressed-timed-modifiers" aria-label="Permalink to “Tag-addressed timed modifiers”">​</a></h2><p>A tag names a group of attributes configured together, so one call can apply a whole buff without listing its parts.</p><h3 id="attribute-tag-add" tabindex="-1">attribute_tag_add <a class="header-anchor" href="#attribute-tag-add" aria-label="Permalink to “attribute_tag_add”">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>tag</code></td><td>STRING</td><td>Yes</td><td>—</td><td>Attribute tag, case-insensitive.</td></tr><tr><td><code>value</code></td><td>DOUBLE</td><td>Yes</td><td>—</td><td>Modifier value applied to every matching attribute.</td></tr><tr><td><code>duration_ticks</code></td><td>DURATION</td><td>Yes</td><td>—</td><td>How long the modifiers last.</td></tr><tr><td><code>effect_prefix</code></td><td>STRING</td><td>No</td><td><code>tag:&lt;tag&gt;</code></td><td><strong>Effect group id</strong> that every matched attribute joins. Empty uses <code>tag:&lt;tag&gt;</code>.</td></tr><tr><td><code>stack_mode</code></td><td>STRING</td><td>No</td><td><code>&quot;&quot;</code></td><td>Stack mode: <code>REPLACE</code> or <code>STACK</code>. Blank uses each attribute&#39;s own <code>temporary_stack_mode</code>; an unrecognised value fails with <code>INVALID_CONFIG</code>.</td></tr></tbody></table><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | attribute_tag_add tag=DEBUFF value=-5 duration_ticks=5s effect_prefix=poison stack_mode=REPLACE&#39;</span></span></code></pre></div><p>Every attribute matched above lands in the single <code>poison</code> group, so <code>attribute_remove effect_id=poison</code> clears the whole set.</p><h3 id="attribute-tag-remove-attribute-tag-clear" tabindex="-1">attribute_tag_remove / attribute_tag_clear <a class="header-anchor" href="#attribute-tag-remove-attribute-tag-clear" aria-label="Permalink to “attribute_tag_remove / attribute_tag_clear”">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>tag</code></td><td>STRING</td><td>Yes</td><td>—</td><td>Attribute tag whose timed modifiers should be removed.</td></tr></tbody></table><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | attribute_tag_remove tag=DEBUFF&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | attribute_tag_clear tag=BUFF&#39;</span></span></code></pre></div><p>These two behave identically: both remove by tag. The duplication is carried over from the previous implementation. Deciding what <code>clear</code> was meant to do (drop every tag, presumably) would change behaviour that existing configuration may depend on, so it was left alone.</p><p>A blank <code>tag</code> fails with <code>INVALID_CONFIG</code>; when no attribute carries the tag, or the target has no matching effect, the stage is <code>skipped</code> rather than reported successful. All three stages report <code>tag</code>, <code>effect_id</code>, <code>status</code>, and <code>count</code> (how many attributes were matched and processed) on success.</p><h2 id="sync" tabindex="-1">Sync <a class="header-anchor" href="#sync" aria-label="Permalink to “Sync”">​</a></h2><p>Both stages take a single parameter; they differ in its default and in whether caches are dropped.</p><table tabindex="0"><thead><tr><th>Stage ID</th><th>Parameter</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>attribute_sync</code></td><td><code>all</code></td><td>BOOLEAN</td><td><code>false</code></td><td>Recomputes values without dropping caches. Defaults to the target only.</td></tr><tr><td><code>attribute_refresh</code></td><td><code>all</code></td><td>BOOLEAN</td><td><code>true</code></td><td>Drops the module&#39;s caches, then recomputes. This is the stage to run after editing attribute configuration. Defaults to every online player.</td></tr></tbody></table><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">  # Sync yourself only</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | attribute_sync&#39;</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">  # Sync every online player; no target needed, so the source can be omitted</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;attribute_sync all=true&#39;</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">  # After a config change: drop caches and recompute server-wide</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;attribute_refresh&#39;</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">  # Drop caches and recompute for yourself only</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | attribute_refresh all=false&#39;</span></span></code></pre></div><p>Both declare <code>OPTIONAL</code> rather than <code>REQUIRED_ENTITY</code>, because <code>all=true</code> needs no target at all; the per-target path checks for a player itself and skips when there is none.</p><p>These are also the only stages in this module whose thread domain depends on their arguments: <code>all=true</code> walks the online-player list and runs on the server-global domain, while <code>all=false</code> touches a single entity. When <code>all</code> is written as a placeholder it cannot be read during planning, so the stage&#39;s own default decides the domain, which means <code>attribute_refresh</code> is planned as global.</p><p>On success the stage reports <code>all</code>, plus <code>player</code> when <code>all=false</code>.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to “Notes”">​</a></h2><ul><li>Apart from <code>attribute_sync all=true</code> and <code>attribute_refresh all=true</code>, every stage on this page needs a player target.</li><li>To add or clear timed modifiers on a mob directly from a MythicMobs skill, use <code>emaki_attribute_add</code>, <code>emaki_attribute_remove</code>, <code>emaki_attribute_add_tag</code>, and <code>emaki_attribute_clear_tag</code> from <a href="./mythic.html">MythicMobs Integration</a>. Those are MythicMobs mechanics, not the CoreLib stages on this page.</li><li><code>duration_ticks</code> is parsed as CoreLib DURATION: <code>20t</code>, <code>1s</code>, and <code>1000ms</code> all work, and a plain number is ticks.</li><li>When the relevant service is not ready, the stage fails with <code>MISSING_CONTEXT</code> rather than skipping silently.</li></ul>`,53)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};